-- InternExam core schema. Apply with `supabase db push` before starting the application.
create extension if not exists pgcrypto;
create type public.app_role as enum ('STUDENT','ADMIN');
create type public.direction as enum ('PYTHON','JAVASCRIPT','FLUTTER');
create type public.exam_state as enum ('DRAFT','PUBLISHED','ARCHIVED');
create type public.attempt_state as enum ('NOT_STARTED','IN_PROGRESS','PASSED','FAILED','UNDER_REVIEW','EXPIRED');
create type public.violation_type as enum ('TAB_HIDDEN','WINDOW_BLUR','PAGE_EXIT','PAGE_RELOAD','NAVIGATION','OFFLINE','ONLINE','HEARTBEAT_MISSING','REOPENED');

create table public.groups (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.mentors (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null unique, role public.app_role not null default 'STUDENT', direction public.direction not null, group_id uuid references public.groups(id), mentor_id uuid references public.mentors(id), created_at timestamptz not null default now());
create table public.exams (id uuid primary key default gen_random_uuid(), title text not null, direction public.direction not null, state public.exam_state not null default 'DRAFT', duration_minutes int not null default 60 check(duration_minutes between 5 and 360), pass_percentage numeric(5,2) not null default 70 check(pass_percentage between 0 and 100), question_count int, reveal_result boolean not null default true, max_violations int not null default 3, violation_action text not null default 'WARN' check(violation_action in ('WARN','REVIEW','AUTO_FINISH')), created_at timestamptz not null default now());
create table public.questions (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams(id) on delete cascade, source_key text not null, body text not null, code_block text, difficulty smallint not null check(difficulty between 1 and 3), correct_option_id uuid, key_confirmed boolean not null default false, created_at timestamptz not null default now(), unique(exam_id,source_key));
create table public.question_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, position smallint not null check(position between 1 and 4), body text not null, unique(question_id,position));
alter table public.questions add constraint questions_correct_option_fk foreign key(correct_option_id) references public.question_options(id) deferrable initially deferred;
create table public.attempts (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id), exam_id uuid not null references public.exams(id), state public.attempt_state not null default 'IN_PROGRESS', started_at timestamptz not null default now(), deadline_at timestamptz not null, finished_at timestamptz, question_total int not null, correct_total int not null default 0, wrong_total int not null default 0, skipped_total int not null default 0, percentage numeric(5,2), violation_count int not null default 0, last_heartbeat_at timestamptz not null default now(), unique(student_id,exam_id));
create table public.attempt_questions (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, question_id uuid not null references public.questions(id), ordinal int not null, option_order uuid[] not null, selected_option_id uuid references public.question_options(id), answered_at timestamptz, unique(attempt_id,question_id),unique(attempt_id,ordinal));
create table public.violation_events (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, student_id uuid not null references public.profiles(id), type public.violation_type not null, technical_context jsonb not null default '{}', occurred_at timestamptz not null default now(), dedupe_key text not null, unique(attempt_id,dedupe_key));
create index attempts_student_idx on public.attempts(student_id); create index attempts_exam_idx on public.attempts(exam_id); create index violations_attempt_idx on public.violation_events(attempt_id,occurred_at desc);

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='ADMIN') $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email,direction,group_id,mentor_id) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email,(new.raw_user_meta_data->>'direction')::public.direction,nullif(new.raw_user_meta_data->>'group_id','')::uuid,nullif(new.raw_user_meta_data->>'mentor_id','')::uuid); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

-- Published exams are impossible when a key is incomplete.
create or replace function public.assert_publishable_exam() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.state='PUBLISHED' and exists(select 1 from public.questions where exam_id=new.id and (not key_confirmed or correct_option_id is null)) then raise exception 'All question keys must be confirmed before publishing'; end if; return new; end; $$;
create trigger exam_publish_guard before update of state on public.exams for each row execute procedure public.assert_publishable_exam();

create or replace function public.start_exam(p_exam_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_exam public.exams%rowtype;v_id uuid;v_total int; begin if not exists(select 1 from profiles where id=v_user and role='STUDENT') then raise exception 'student access required';end if; select * into v_exam from exams where id=p_exam_id and state='PUBLISHED' and direction=(select direction from profiles where id=v_user);if not found then raise exception 'No available published exam';end if; if exists(select 1 from attempts where student_id=v_user and exam_id=p_exam_id) then raise exception 'Attempt already exists';end if; insert into attempts(student_id,exam_id,deadline_at,question_total) values(v_user,p_exam_id,now()+make_interval(mins=>v_exam.duration_minutes),0) returning id into v_id; insert into attempt_questions(attempt_id,question_id,ordinal,option_order) select v_id,q.id,row_number() over(order by random()),array(select o.id from question_options o where o.question_id=q.id order by random()) from questions q where q.exam_id=p_exam_id order by random(); get diagnostics v_total=row_count; update attempts set question_total=v_total where id=v_id; return v_id;end; $$;

create or replace function public.save_attempt_answer(p_attempt_id uuid,p_question_id uuid,p_option_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from attempts where id=p_attempt_id and student_id=auth.uid() and state='IN_PROGRESS' and deadline_at>now()) then raise exception 'Attempt locked or expired';end if; if not exists(select 1 from attempt_questions aq join question_options o on o.id=p_option_id and o.question_id=aq.question_id where aq.attempt_id=p_attempt_id and aq.question_id=p_question_id) then raise exception 'Invalid option';end if; update attempt_questions set selected_option_id=p_option_id,answered_at=now() where attempt_id=p_attempt_id and question_id=p_question_id;end; $$;
create or replace function public.finalize_attempt(p_attempt_id uuid) returns public.attempts language plpgsql security definer set search_path=public as $$ declare v public.attempts%rowtype;v_correct int;v_answered int;begin select * into v from attempts where id=p_attempt_id and student_id=auth.uid() for update;if not found then raise exception 'Attempt not found';end if;if v.state<>'IN_PROGRESS' then return v;end if;select count(*) filter(where aq.selected_option_id=q.correct_option_id),count(*) filter(where aq.selected_option_id is not null) into v_correct,v_answered from attempt_questions aq join questions q on q.id=aq.question_id where aq.attempt_id=v.id;update attempts set state=case when violation_count>(select max_violations from exams where id=v.exam_id) and (select violation_action from exams where id=v.exam_id)='REVIEW' then 'UNDER_REVIEW' when coalesce(v_correct,0)::numeric/v.question_total*100 >= (select pass_percentage from exams where id=v.exam_id) then 'PASSED' else 'FAILED' end,finished_at=now(),correct_total=coalesce(v_correct,0),wrong_total=coalesce(v_answered,0)-coalesce(v_correct,0),skipped_total=v.question_total-coalesce(v_answered,0),percentage=round(coalesce(v_correct,0)::numeric/v.question_total*100,2) where id=v.id returning * into v;return v;end; $$;
create or replace function public.record_violation(p_attempt_id uuid,p_type public.violation_type,p_context jsonb,p_dedupe_key text) returns int language plpgsql security definer set search_path=public as $$ declare n int;begin if not exists(select 1 from attempts where id=p_attempt_id and student_id=auth.uid() and state='IN_PROGRESS') then raise exception 'Attempt inactive';end if;insert into violation_events(attempt_id,student_id,type,technical_context,dedupe_key) values(p_attempt_id,auth.uid(),p_type,coalesce(p_context,'{}'),p_dedupe_key) on conflict(attempt_id,dedupe_key) do nothing;update attempts set violation_count=(select count(*) from violation_events where attempt_id=p_attempt_id),last_heartbeat_at=now() where id=p_attempt_id returning violation_count into n;return n;end; $$;
create or replace function public.heartbeat(p_attempt_id uuid) returns timestamptz language plpgsql security definer set search_path=public as $$ declare v timestamptz;begin update attempts set last_heartbeat_at=now() where id=p_attempt_id and student_id=auth.uid() and state='IN_PROGRESS' returning deadline_at into v;if v is null then raise exception 'Attempt inactive';end if;return v;end; $$;

alter table public.groups enable row level security; alter table public.mentors enable row level security; alter table public.profiles enable row level security; alter table public.exams enable row level security; alter table public.questions enable row level security; alter table public.question_options enable row level security; alter table public.attempts enable row level security; alter table public.attempt_questions enable row level security; alter table public.violation_events enable row level security;
create policy groups_read on public.groups for select to authenticated using(active or is_admin()); create policy groups_admin on public.groups for all to authenticated using(is_admin()) with check(is_admin());
create policy mentors_read on public.mentors for select to authenticated using(active or is_admin()); create policy mentors_admin on public.mentors for all to authenticated using(is_admin()) with check(is_admin());
create policy profile_self on public.profiles for select to authenticated using(id=auth.uid() or is_admin()); create policy profile_admin on public.profiles for update to authenticated using(is_admin()) with check(is_admin());
create policy exam_read on public.exams for select to authenticated using(is_admin() or (state='PUBLISHED' and direction=(select direction from profiles where id=auth.uid())));create policy exam_admin on public.exams for all to authenticated using(is_admin()) with check(is_admin());
create policy questions_admin on public.questions for all to authenticated using(is_admin()) with check(is_admin());create policy options_admin on public.question_options for all to authenticated using(is_admin()) with check(is_admin());
create policy attempts_read on public.attempts for select to authenticated using(student_id=auth.uid() or is_admin());create policy aq_read on public.attempt_questions for select to authenticated using(exists(select 1 from attempts a where a.id=attempt_id and (a.student_id=auth.uid() or is_admin())));create policy violations_read on public.violation_events for select to authenticated using(student_id=auth.uid() or is_admin());
revoke all on function public.start_exam(uuid),public.save_attempt_answer(uuid,uuid,uuid),public.finalize_attempt(uuid),public.record_violation(uuid,public.violation_type,jsonb,text),public.heartbeat(uuid) from public; grant execute on function public.start_exam(uuid),public.save_attempt_answer(uuid,uuid,uuid),public.finalize_attempt(uuid),public.record_violation(uuid,public.violation_type,jsonb,text),public.heartbeat(uuid) to authenticated;
